const today = new Date().toISOString().slice(0, 10);

return items.filter(item => {
  const created = item.json.created_at;
  if (!created) return false;

  return created.startsWith(today);
});

const now = new Date();

const dateString = now.toLocaleDateString('en-GB', {
  weekday: 'short',
  day: '2-digit',
  month: 'short',
  year: 'numeric',
  timeZone: 'Asia/Kolkata'
});

const timeString = now.toLocaleString('en-GB', {
  day: '2-digit',
  month: 'short',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  hour12: true,
  timeZone: 'Asia/Kolkata'
});

let total = 0;
let critical = 0, high = 0, medium = 0, low = 0;
let statusOpen = 0, statusInvestigating = 0, statusEscalated = 0;
let statusResolved = 0, statusFalsePositive = 0;
let statusContained = 0;
let criticalOpen = 0;
let slaBreach = 0, metSLA = 0;
let totalResolutionTime = 0;
let resolvedCount = 0;
let ageUnder1h = 0, ageUnder4h = 0, ageUnder24h = 0, ageOver24h = 0;

const analystPerformance = {};
const topRules = {};
const tactics = {};
const hostCounts = {};
const userCounts = {};

for (const item of items) {
  const alert = item.json;
  total++;

  const severity = (alert.severity || "").toLowerCase().trim();
  const rawStatus = (alert.status || "").toLowerCase().trim().replace(/[\s\-]+/g, "_");

  // Severity
  if (severity === "critical") critical++;
  else if (severity === "high") high++;
  else if (severity === "medium") medium++;
  else if (severity === "low") low++;

  // Status
  const isOpen          = rawStatus === "open";
  const isInvestigating = rawStatus === "investigating";
  const isEscalated     = rawStatus === "escalated";
  const isResolved      = rawStatus === "resolved" || rawStatus === "closed";
  const isContained = rawStatus === "contained";
  const isFP            = rawStatus === "false_positive" || rawStatus === "falsepositive";

  // ✅ SOC FIX: Treat FP as resolved for lifecycle metrics
  const isEffectivelyResolved = isResolved || isFP;

  if (isOpen)          statusOpen++;
  if (isInvestigating) statusInvestigating++;
  if (isEscalated)     statusEscalated++;
  if (isResolved)      statusResolved++;        // keep real resolved only
  if (isContained) statusContained++;
  if (isFP)            statusFalsePositive++;   // track FP separately

  // Critical Open
  if (severity === "critical" && (isOpen || isInvestigating || isEscalated)) {
    criticalOpen++;
  }

  // Age + SLA
  if (alert.created_at) {
    const created = new Date(alert.created_at);
    const diffMin = (now - created) / (1000 * 60);

    if (diffMin < 60)        ageUnder1h++;
    else if (diffMin < 240)  ageUnder4h++;
    else if (diffMin < 1440) ageUnder24h++;
    else                     ageOver24h++;

    // ✅ UPDATED: use effective resolved
    if (isEffectivelyResolved) {
      resolvedCount++;
      totalResolutionTime += diffMin;

      if (diffMin <= 30) metSLA++;
      else slaBreach++;

    } else if (isOpen || isInvestigating || isEscalated) {
      if (diffMin > 30) slaBreach++;
    }

    // Analyst tracking
    const analyst = alert.analyst || "Unassigned";
    if (!analystPerformance[analyst]) {
      analystPerformance[analyst] = { closed: 0, fp: 0 };
    }

    // ✅ UPDATED: FP counts as closed work
    if (isEffectivelyResolved) analystPerformance[analyst].closed++;
    if (isFP) analystPerformance[analyst].fp++;
  }

  const rule = alert.rule_name || "Unknown";
  topRules[rule] = (topRules[rule] || 0) + 1;

  const tactic = alert.mitre_tactic || "Unknown";
  tactics[tactic] = (tactics[tactic] || 0) + 1;

  const host = alert.host || alert.src_ip || "Unknown Host";
  hostCounts[host] = (hostCounts[host] || 0) + 1;

  const user = alert.user || "Unknown User";
  userCounts[user] = (userCounts[user] || 0) + 1;
}

const avgMTTR  = resolvedCount > 0 ? Math.round(totalResolutionTime / resolvedCount) : 0;
const fpRate   = total > 0 ? Math.round((statusFalsePositive / total) * 100) : 0;

const analystSummary = Object.keys(analystPerformance).length
  ? Object.entries(analystPerformance)
      .map(([a, d]) => `• ${a}: ${d.closed} closed / ${d.fp} FP`)
      .join("\n")
  : "No analyst activity today";

const topRulesSummary = Object.entries(topRules)
  .sort((a, b) => b[1] - a[1]).slice(0, 5)
  .map(([r, c]) => `• ${r}: ${c}`)
  .join("\n");

const tacticSummary = Object.entries(tactics)
  .sort((a, b) => b[1] - a[1]).slice(0, 5)
  .map(([t, c]) => `• ${t}: ${c}`)
  .join("\n");

const topHost = Object.entries(hostCounts).sort((a,b)=>b[1]-a[1])[0];
const topUser = Object.entries(userCounts).sort((a,b)=>b[1]-a[1])[0];

const topHostSummary = topHost ? `${topHost[0]}  _(${topHost[1]} alerts)_` : "N/A";
const topUserSummary = topUser ? `${topUser[0]}  _(${topUser[1]} alerts)_` : "N/A";

let keyInsight = "";
if (criticalOpen > 0)
  keyInsight = `🚨 ${criticalOpen} critical alert(s) currently open — immediate action needed`;
else if (critical > 5)
  keyInsight = "🚨 High volume of critical alerts detected today";
else if (fpRate > 30)
  keyInsight = "⚠️ High false positive rate observed — review detection rules";
else
  keyInsight = "✅ Normal SOC operations";

const slaBadge   = slaBreach > 0 ? "⚠️ Breaches present" : "✅ All within SLA";
const mttrBadge  = avgMTTR > 60 ? "⚠️ Slow" : avgMTTR > 0 ? "✅ Good" : "—";
const fpBadge    = fpRate > 30 ? "⚠️ High" : fpRate > 15 ? "〽️ Elevated" : "✅ Normal";
const ageBadge   = ageOver24h > 0 ? `⚠️ ${ageOver24h} stale` : "✅ All fresh";
const critBadge  = criticalOpen > 0 ? `🔴 ${criticalOpen} need action` : "✅ None active";

return [{
  json: {
    dateString, timeString,
    total, critical, high, medium, low,
    statusOpen, statusInvestigating, statusEscalated, statusResolved, statusFalsePositive,
    criticalOpen, fpRate, fpBadge,
    avgMTTR, mttrBadge,
    slaBreach, metSLA, slaBadge,
    ageUnder1h, ageUnder4h, ageUnder24h, ageOver24h, ageBadge,
    critBadge,
    analystSummary, topRulesSummary, tacticSummary,
    topHostSummary, topUserSummary,
    keyInsight
  }
}];

